def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            objects.append((color, cells))

    def signature(cells):
        top = min(r for r, _ in cells)
        left = min(c for _, c in cells)
        return frozenset((r - top, c - left) for r, c in cells)

    for target_color, cells in objects:
        top = min(r for r, _ in cells)
        bottom = max(r for r, _ in cells)
        left = min(c for _, c in cells)
        right = max(c for _, c in cells)
        target_set = set(cells)
        missing = [(r, c) for r in range(top, bottom + 1)
                   for c in range(left, right + 1) if (r, c) not in target_set]
        if not missing:
            continue
        missing_set = set(missing)
        holes = []
        while missing_set:
            start = missing_set.pop()
            stack = [start]
            hole = [start]
            while stack:
                y, x = stack.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if p in missing_set:
                        missing_set.remove(p)
                        stack.append(p)
                        hole.append(p)
            holes.append(hole)
        unused = list(range(len(objects)))
        assignments = []
        possible = True
        for hole in holes:
            sig = signature(hole)
            match = None
            for i in unused:
                if objects[i][0] != target_color and signature(objects[i][1]) == sig:
                    match = i
                    break
            if match is None:
                possible = False
                break
            unused.remove(match)
            assignments.append((hole, objects[match][0]))
        if possible:
            result = [[bg] * (right - left + 1) for _ in range(bottom - top + 1)]
            for r, c in cells:
                result[r - top][c - left] = target_color
            for hole, color in assignments:
                for r, c in hole:
                    result[r - top][c - left] = color
            return result
    return []
